static int* parse(const char* line,int* n){const char* l=strchr(line,'[');if(!l){*n=0;return NULL;}l=strchr(l+1,'[');const char* r=strrchr(line,']');if(!l||!r||r<=l){*n=0;return NULL;}size_t len=(size_t)(r-l-1);char* buf=(char*)malloc(len+1);memcpy(buf,l+1,len);buf[len]='\0';if(len==0){free(buf);*n=0;return NULL;}int count=1;for(size_t i=0;i<len;i++)if(buf[i]==',')count++;int* a=(int*)malloc(sizeof(int)*count);int k=0;char* tok=strtok(buf,",");while(tok){a[k++]=atoi(tok);tok=strtok(NULL,",");}free(buf);*n=k;return a;}
bool validUtf8(int* data,int dataSize){int remaining=0;for(int i=0;i<dataSize;i++){int b=data[i];if(remaining==0){if((b>>7)==0)continue;if((b>>5)==6)remaining=1;else if((b>>4)==14)remaining=2;else if((b>>3)==30)remaining=3;else return false;}else{if((b>>6)!=2)return false;remaining--;}}return remaining==0;}

